import React, { useState, useEffect } from 'react';
import './App.css';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Analytics from './pages/Analytics';
import Reports from './pages/Reports';

function App() {
  const [token, setToken] = useState(null);
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [stats, setStats] = useState({ total: 0, anomalies: 0, normal: 0 });
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const savedToken = localStorage.getItem('token');
    if (savedToken) {
      setToken(savedToken);
    }
  }, []);

  useEffect(() => {
    if (token) {
      localStorage.setItem('token', token);
    } else {
      localStorage.removeItem('token');
    }
  }, [token]);

  const addNotification = (message, type = 'info') => {
    const notification = {
      id: Date.now(),
      message,
      type,
      timestamp: new Date()
    };
    setNotifications(prev => [notification, ...prev.slice(0, 4)]); // Keep only 5 notifications

    // Auto remove after 5 seconds
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== notification.id));
    }, 5000);
  };

  if (!token) {
    return <Login setToken={setToken} />;
  }

  return (
    <div className="app-layout">
      {/* Sidebar */}
      <div className="sidebar">
        <div className="sidebar-header">
          <div className="sidebar-logo">
            <div className="logo">AD</div>
            <div className="brand-text">
              <h3>Anomaly Detection</h3>
              <span>Financial Security</span>
            </div>
          </div>
        </div>

        <nav className="sidebar-nav">
          <button 
            className={`sidebar-item ${currentPage === 'dashboard' ? 'active' : ''}`}
            onClick={() => setCurrentPage('dashboard')}
          >
            <span className="sidebar-icon">🏠</span>
            Dashboard
          </button>
          <button 
            className={`sidebar-item ${currentPage === 'analytics' ? 'active' : ''}`}
            onClick={() => setCurrentPage('analytics')}
          >
            <span className="sidebar-icon">📊</span>
            Analytics
          </button>
          <button 
            className={`sidebar-item ${currentPage === 'reports' ? 'active' : ''}`}
            onClick={() => setCurrentPage('reports')}
          >
            <span className="sidebar-icon">📋</span>
            Reports
          </button>
        </nav>

        <div className="sidebar-footer">
          <div className="user-info">
            <div className="user-avatar">A</div>
            <div className="user-details">
              <div className="user-name">Admin</div>
              <div className="user-role">System Administrator</div>
            </div>
          </div>
          <button className="logout-btn" onClick={() => setToken(null)}>
            🚪 Logout
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="main-layout">
        <div className="page-header">
          <div className="header-content">
            <div>
              <div className="breadcrumb">
                <span className="breadcrumb-item">Home</span>
                <span className="breadcrumb-separator">/</span>
                <span className="breadcrumb-item active">{currentPage.charAt(0).toUpperCase() + currentPage.slice(1)}</span>
              </div>
              <h1 className="page-title">
                {currentPage === 'dashboard' && 'Transaction Dashboard'}
                {currentPage === 'analytics' && 'Analytics & Insights'}
                {currentPage === 'reports' && 'Compliance Reports'}
              </h1>
              <p className="page-subtitle">
                {currentPage === 'dashboard' && 'Monitor and manage financial transactions with real-time anomaly detection'}
                {currentPage === 'analytics' && 'Comprehensive analysis of transaction patterns and ML model performance'}
                {currentPage === 'reports' && 'Generate detailed compliance and audit reports'}
              </p>
            </div>
            <div className="header-actions">
              <div className="quick-stats">
                <div className="quick-stat">
                  <span className="stat-value">{stats.total}</span>
                  <span className="stat-label">Total</span>
                </div>
                <div className="quick-stat anomaly">
                  <span className="stat-value">{stats.anomalies}</span>
                  <span className="stat-label">Alerts</span>
                </div>
              </div>
              <div className="header-buttons">
                {/* Notification display in header stats instead of bell icon */}
              </div>
            </div>
          </div>

          {/* Notification Panel */}
          {notifications.length > 0 && (
            <div className="notification-panel">
              {notifications.map(notification => (
                <div key={notification.id} className={`notification-item ${notification.type}`}>
                  <div className="notification-content">
                    <span className="notification-message">{notification.message}</span>
                    <span className="notification-time">
                      {notification.timestamp.toLocaleTimeString()}
                    </span>
                  </div>
                  <button 
                    className="notification-close"
                    onClick={() => setNotifications(prev => prev.filter(n => n.id !== notification.id))}
                  >
                    ×
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>

        {currentPage === 'dashboard' && (
          <Dashboard token={token} setToken={setToken} setStats={setStats} addNotification={addNotification} />
        )}
        {currentPage === 'analytics' && (
          <Analytics token={token} />
        )}
        {currentPage === 'reports' && (
          <Reports token={token} />
        )}
      </div>
    </div>
  );
}

export default App;
